const parseData = (csv) => {
  const lines = csv.split('\n').slice(1);
  return lines.map(line => {
    const values = line.split(',');
    const sizeMatch = values[1]?.match(/\d+/);
    const refreshMatch = values[5]?.match(/(\d+)/);
    const msrp = parseFloat(values[7]) || 0;
    const finalPrice = parseFloat(values[8]) || 0;
    const isDamaged = values[10]?.toLowerCase().includes('yes');
    
    return {
      name: values[0],
      size: sizeMatch ? parseInt(sizeMatch[0]) : 0,
      resolution: values[2],
      brand: values[0]?.split(' ')[0] || 'Unknown',
      curve: values[4],
      refreshRate: refreshMatch ? parseInt(refreshMatch[0]) : 0,
      msrp,
      finalPrice,
      valueRetention: msrp > 0 ? (finalPrice / msrp * 100) : 0,
      isDamaged
    };
  }).filter(item => item.size > 0 && item.finalPrice > 0);
};

